def _parse(v):
    """Split a version string into (core, prerelease, build)."""
    s = v.strip()
    build = None
    if "+" in s:
        s, build = s.split("+", 1)
    pre = None
    if "-" in s:
        s, pre = s.split("-", 1)
    core = tuple(int(p) for p in s.split("."))
    return core, pre, build


def _identifier_key(ident):
    if ident.isdigit():
        # Numeric identifiers are lower than alphanumeric ones and
        # compare as integers.
        return (0, int(ident), "")
    return (1, 0, ident)


def _pre_key(pre):
    # A version without a pre-release has higher precedence than any
    # version with one.
    if pre is None:
        return (1,)
    return (0, tuple(_identifier_key(i) for i in pre.split(".")))


def sort_key(v):
    core, pre, _build = _parse(v)
    return (core, _pre_key(pre))


def sort_versions(vs):
    """Return versions sorted by SemVer 2.0.0 precedence, lowest first.

    Build metadata is ignored for ordering and ties keep input order.
    """
    return sorted(vs, key=sort_key)
